sys_script.script:
(function executeRule(current, previous) {

    var roleMap = {
        'Cement': 'TSH',
        'BPD': 'TSH_BPD',
        'RMC': 'TSM',
        'Ready Mix concrete': 'TSM'
    };

    var segment = current.getValue('segment');
    var role = roleMap[segment];

    if (!role) {
        gs.info('CLM: No role mapping defined for segment=' + segment + ' on customer ' + current.getValue('number'));
        return;
    }

    // Only recompute if something relevant changed (or tsh not yet set)
    if (!current.tsh.nil() && !current.zone.changes() && !current.region.changes() &&
        !current.depot.changes() && !current.segment.changes()) {
        return;
    }

    var zone = current.getValue('zone');
    var region = current.getValue('region');
    var depot = current.getValue('depot');

    // Resolve the correct user for this key
    var mapping = new GlideRecord('x_birl3_clm_role_user_mapping');
    mapping.addActiveQuery();
    mapping.addQuery('u_role', role);
    mapping.addQuery('u_segment', segment);
    mapping.addQuery('u_zone', zone);
    mapping.addQuery('u_region', region);
    if (role !== 'TSM') {
        mapping.addQuery('u_depot', depot);
    }
    mapping.query();

    if (!mapping.next()) {
        gs.info('CLM: No ' + role + ' mapping found for customer ' + current.getValue('number') +
                ' (segment=' + segment + ', zone=' + zone + ', region=' + region + ', depot=' + depot + ')');
        return;
    }

    var resolvedUser = mapping.getValue('u_user');

    // Find the SHARED TSH record by combo key (NOT by customer)
    var tsh = new GlideRecord('x_birl3_clm_tsh');
    tsh.addQuery('u_role', role);
    tsh.addQuery('segment', segment);
    tsh.addQuery('zone', zone);
    tsh.addQuery('region', region);
    if (role !== 'TSM') {
        tsh.addQuery('depot', depot);
    }
    tsh.query();

    var tshSysId;
    if (tsh.next()) {
        if (tsh.getValue('name') !== resolvedUser) {
            tsh.setValue('name', resolvedUser);
            tsh.update();
        }
        tshSysId = tsh.getUniqueValue();
    } else {
        var newTsh = new GlideRecord('x_birl3_clm_tsh');
        newTsh.initialize();
        newTsh.setValue('name', resolvedUser);
        newTsh.setValue('u_role', role);
        newTsh.setValue('zone', zone);
        newTsh.setValue('zone_name', current.getValue('zone_name'));
        newTsh.setValue('region', region);
        newTsh.setValue('region_name', current.getValue('region_name'));
        newTsh.setValue('depot', role !== 'TSM' ? depot : '');
        newTsh.setValue('segment', segment);
        tshSysId = newTsh.insert();
    }

    current.tsh = tshSysId;

})(current, previous);
